COLUMN_COMMENTS_FOR_CHECK = GOLD_TDX_COLUMN_COMMENTS

def assert_not_boilerplate(text, where):
    """Raise when a comment is missing or is a generator template (INSR W8.04, F17)."""
    if text is None or not str(text).strip() or any(re.search(p, str(text).strip()) for p in BOILERPLATE_PATTERNS):
        raise ValueError(f"INSR_W8_COMMENTS_V1: template or missing comment for {where}")


for _table, _columns in list(COLUMN_COMMENTS_FOR_CHECK.items()):
    for _column, _text in _columns.items():
        assert_not_boilerplate(_text, f"{_table}.{_column}")
